CREATE TABLE IF NOT EXISTS enquiry_drafts (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, message TEXT NOT NULL, created_at TEXT NOT NULL, deleted_at TEXT, source_system TEXT, source_id TEXT, CHECK(length(trim(message)) BETWEEN 1 AND 10000), CHECK((source_system IS NULL AND source_id IS NULL) OR (source_system IS NOT NULL AND source_id IS NOT NULL))); CREATE INDEX IF NOT EXISTS enquiry_drafts_owner_idx ON enquiry_drafts(user_id, created_at); CREATE UNIQUE INDEX IF NOT EXISTS enquiry_drafts_source_idx ON enquiry_drafts(source_system, source_id); CREATE TABLE IF NOT EXISTS import_identity_mappings (id TEXT PRIMARY KEY NOT NULL, source_system TEXT NOT NULL, source_user_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, created_at TEXT NOT NULL); CREATE UNIQUE INDEX IF NOT EXISTS import_identity_source_idx ON import_identity_mappings(source_system, source_user_id);
